-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.rogue.dps.Name"] = "近戰 DPS"
L["rm.era.rogue.dps.Description"] = "1–60 級，所有專精，也適用於專家模式與獨行模式伺服器；綜合 模擬器、Icy Veins 與 Wowhead。潛行時：預謀，目標未面向你且持有匕首時伏擊，單人時偷襲，團隊以外絞喉。戰鬥中：還擊，精英或生命力充足的目標身上沒有切割時從一個連擊點起使用切割（在最後三秒內於五個連擊點時續上），隊伍中擁有強化破甲 2/2 且沒有人使用破甲攻擊時在五個連擊點使用破甲，對即將死亡的目標使用兩點剔骨，否則在五個連擊點時使用剔骨，且超過五點後不再使用累積連擊點技能。累積連擊點技能取決於你已學會的技能：團隊以外使用鬼魅攻擊與出血，目標未面向你且持有匕首時使用背刺，否則使用邪惡攻擊。提醒：每把武器上的毒藥（若攜帶副手武器，副手使用致命毒藥）、腳踢、菊花茶、對精英或兩個敵人且切割生效時使用劍刃亂舞與能量刺激、五個連擊點時使用冷血、單人受傷時使用閃避。消失、鑿擊、伺機待發、腎擊與種族技能列出但預設關閉；佯攻、疾跑、致盲、悶棍與站位由你自行處理。"
L["rm.era.rogue.dps.simulator.Name"] = "劍類武器，配合揮擊的邪惡攻擊（模擬器）"
L["rm.era.rogue.dps.simulator.Description"] = "模擬器 針對劍類武器專精的「極限」戰鬥順序，作為推薦的近戰傷害輸出內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。邪惡攻擊只在主手揮擊後立即使用（距離下一次揮擊 2.0 秒以上，針對速度 2.6–2.8 的劍設定；可在複製的循環中修改），除非能量接近全滿或目標即將死亡，這樣額外的劍類攻擊就不會延遲你的揮擊。五個連擊點的剔骨也會等待切割、能量全滿或目標即將死亡。其餘與推薦的內建循環相同。"
L["rm.era.rogue.dps.warcrafttavern.Name"] = "近戰 DPS，五連擊點終結技（Warcraft Tavern）"
L["rm.era.rogue.dps.warcrafttavern.Description"] = "Warcraft Tavern 的打法，作為推薦的近戰傷害輸出內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。每個終結技都等到五個連擊點，讓無情打擊返還能量。切割從第二級（42 級）起，在缺少或即將結束時使用，否則使用剔骨；不使用低連擊點切割、不對瀕死目標使用剔骨，也不使用破甲（由戰士的破甲攻擊負責）。潛行起手、累積連擊點技能與提醒都與推薦的內建循環相同。"
L["rm.forever.rogue.dps.Name"] = "近戰 DPS"
L["rm.forever.rogue.dps.Description"] = "適用於所有盜賊專精 1 至 60 級的近戰傷害，綜合 Icy Veins、Wowhead 與 Warcraft Tavern。累積連擊點技能取決於你已學會的技能：截肢（第五個連擊點用邪惡攻擊）、出血、目標未面向你時使用背刺，否則使用邪惡攻擊。潛行時以預謀起手，單人時偷襲，隊伍中面對精英時敏銳使用絞喉，否則使用伏擊或絞喉。維持切割與毒液，隊伍中對精英且沒有戰士疊滿五層破甲攻擊時使用破甲，然後把五個連擊點用於割裂（敏銳，長時間戰鬥）或剔骨，且絕不累積超過五點。提醒：每把武器上的毒藥、腳踢、對怪群與精英使用劍刃亂舞與能量刺激、冷血、閃避、佯攻、菊花茶與伺機待發。由你自行處理：消失、疾跑、腎擊、致盲、悶棍與站位。永久限制了戰鬥資料，因此 Rotation Master 只將此內建循環列出供參考，目前還不會自動選用。"
L["rm.forever.rogue.subtlety.warcrafttavern.Name"] = "敏銳，伏擊流（Warcraft Tavern）"
L["rm.forever.rogue.subtlety.warcrafttavern.Description"] = "Warcraft Tavern 的伏擊/割喉敏銳流派：每次起手都用預謀與伏擊，割喉允許時再次伏擊，以背後的背刺作為累積連擊點技能（目標面向你時用出血），鬼魅攻擊冷卻結束即使用，切割，然後在五個連擊點時使用剔骨，不使用割裂。會提醒你在首領被坦克拉住時消失以再次伏擊。如果你點了割喉天賦，請選擇它而非推薦的盜賊內建循環；它在以敏銳作為主要天賦樹且已點出割喉時適用。毒藥與冷卻技能提醒與推薦的內建循環相同。這是推薦的盜賊傷害輸出內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.forever.rogue.subtlety.wowhead.Name"] = "敏銳，絞喉流（Wowhead）"
L["rm.forever.rogue.subtlety.wowhead.Description"] = "Wowhead 的敏銳：每次起手都用預謀與絞喉，並在循環中使用消失（接著伺機待發），在上一次絞喉結束後再次以絞喉起手。維持切割，隊伍中使用破甲，割裂作為五連擊點終結技，出血是唯一的累積連擊點技能。這會把你的逃生技能消失用在輸出上：請審慎選擇。它在以敏銳作為主要天賦樹、已點出骯髒手段且已學會預謀時適用。毒藥與冷卻技能提醒與推薦的內建循環相同。這是推薦的盜賊傷害輸出內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.mop.rogue.assassination.Name"] = "推薦"
L["rm.mop.rogue.assassination.Description"] = "推薦刺殺使用，適用於 10 至 90 級（第 5 階段依據 模擬器 與 Wowhead，升級步驟依據 Icy Veins）。單人時從潛行以偷襲起手，否則用截肢（洞悉要害觸發時用抹殺，需要匕首）。維持切割（60 級起由毒化刷新）與目標身上的割裂，割裂持續期間將五個連擊點用於毒化，沒有預知時以四個連擊點維持毒化增益效果，然後是死亡標記、低於 35% 或洞悉要害觸發時使用抹殺（主手需要匕首），以及截肢。四個以上敵人與你交戰時：切割、七個敵人時使用赤紅風暴、割裂、毒化與飛舞刀刃；切換目標施放割裂由你決定。單人時加入養精蓄銳，以及生命力低時使用腎擊。提醒：毒藥、腳踢、長時間戰鬥時使用宿怨、搭配宿怨使用暗影之刃、宿怨期間使用消失與準備、從遠處使用暗影閃現、單人時使用閃避。由你自行處理：偷天換日與破甲（列出但預設關閉）、佯攻、疾跑與站位。"
L["rm.mop.rogue.assassination.icyveins.Name"] = "五連擊點毒化（Icy Veins）"
L["rm.mop.rogue.assassination.icyveins.Description"] = "預設關閉。Icy Veins 與 Method 的順序：消失冷卻結束即使用以施放潛行中的截肢，戰鬥夠長時宿怨冷卻結束即使用，毒化只在五個連擊點時使用，維持割裂，低於 35% 或洞悉要害觸發時使用抹殺，截肢。四到八個敵人：飛舞刀刃，三個連擊點以上時使用割裂；九個以上：只用飛舞刀刃與毒化。推薦的刺殺內建循環改為遵循較新的第 5 階段建議；要使用這個，請啟用它並停用推薦的循環。"
L["rm.mop.rogue.combat.Name"] = "推薦"
L["rm.mop.rogue.combat.Description"] = "推薦戰鬥使用，適用於 10 至 90 級（第 5 階段依據 Wowhead 與 模擬器）。自圍攻奧格瑪版本更新起，邪惡攻擊需要 50 點能量，因此以揭底之擊作為累積連擊點技能，邪惡攻擊只在嗜血術或英勇氣概搭配能量刺激期間（以及 20 級前）使用。單人時以偷襲起手，否則用伏擊。從兩個連擊點起維持切割，並維持目標身上的揭底之擊，只在揭底之擊生效時消耗五個連擊點（切割、沒有劍刃亂舞的長時間單一目標戰鬥使用割裂、剔骨），五個連擊點時等待能量。八個以上敵人時：切割、赤紅風暴與飛舞刀刃。單人時加入養精蓄銳與腎擊。提醒：毒藥、腳踢、面對兩個以上敵人時開啟劍刃亂舞並在之後關閉、能量低時搭配暗影之刃使用能量刺激、狂舞殘殺、深度洞察期間為伏擊使用消失與準備、暗影閃現、單人時使用閃避。由你自行處理：偷天換日與破甲（列出但預設關閉）、佯攻，以及為伏擊站在目標背後。"
L["rm.mop.rogue.combat.hekili.Name"] = "預知（Hekili）"
L["rm.mop.rogue.combat.hekili.Description"] = "預設關閉。Hekili 的潘達利亞之謎戰鬥搭配預知順序：揭底之擊是唯一的累積連擊點技能，即使在嗜血術期間也是；終結技會等待深度洞察、四層預知充能或暗影之刃即將回來，然後是切割、對一到兩個長壽目標使用割裂、七個敵人時使用赤紅風暴，以及剔骨；切割在 11 層強盜之詐時提早刷新；四個敵人起使用飛舞刀刃。只在點了預知天賦時適用。要使用它，請啟用它並停用推薦的戰鬥內建循環。"
L["rm.mop.rogue.combat.icyveins.Name"] = "邪惡攻擊累積（Icy Veins）"
L["rm.mop.rogue.combat.icyveins.Description"] = "預設關閉，且在第 5 階段已被取代。圍攻奧格瑪版本更新之前 Icy Veins、Warcraft Tavern、Method 與 wowtbc.gg 的順序：切割、維持揭底之擊、長時間單一目標戰鬥使用五連擊點割裂與剔骨，並以邪惡攻擊作為累積連擊點技能。提醒與怪群打法與推薦的戰鬥內建循環相同。只有在你遵循這些指南時才選擇它；請啟用它並停用推薦的循環。"
L["rm.mop.rogue.subtlety.Name"] = "推薦"
L["rm.mop.rogue.subtlety.Description"] = "推薦點了暗影專注的敏銳使用，適用於 10 至 90 級（第 5 階段依據 模擬器 與 Wowhead）。潛行或暗影之舞期間：預謀、拉怪前使用切割、五個連擊點時使用終結技、伏擊、絞喉。其他情況：切割；五個連擊點時，切割與割裂即將消失就續上，兩者都持續時使用剔骨；死亡標記；以出血維持其流血效果；目標沒有攻擊你且持有匕首時使用背刺，否則使用出血。三個以上敵人時：切割、赤紅風暴、剔骨與飛舞刀刃。單人時加入養精蓄銳與腎擊。提醒：毒藥、腳踢、能量 75 且切割與割裂都生效時使用暗影之舞、找尋弱點即將結束時使用消失、準備、暗影之舞與潛行以外使用暗影之刃、暗影閃現、單人時使用閃避。由你自行處理：站在目標背後（RM 無法看到面向）、偷天換日與破甲（列出但預設關閉）。"
L["rm.mop.rogue.subtlety.warcrafttavern.Name"] = "欺敵（Warcraft Tavern）"
L["rm.mop.rogue.subtlety.warcrafttavern.Description"] = "當你的第一層天賦是欺敵時（Warcraft Tavern 的配置），會自動取代暗影專注內建循環而選用。拉怪前使用預謀與切割；潛行、暗影之舞或欺敵延續期間，五個連擊點時使用終結技，然後盡可能多次使用伏擊。兩到三個敵人：維持割裂，並將五個連擊點用於赤紅風暴而非剔骨；四個以上再加入飛舞刀刃。單一目標：切割、割裂、剔骨、以出血維持其流血效果、持有匕首時在背後使用背刺，否則使用出血。暗影之舞與消失會在能量 60 且切割生效時提醒；依 Tavern 的建議配合飾品觸發時機使用則由你決定。"
L["rm.mop.rogue.unspecialized.Name"] = "未選擇專精"
L["rm.mop.rogue.unspecialized.Description"] = "適用於 1 至 9 級，或尚未選擇專精的盜賊；選擇專精後由各專精的內建循環接手。單人時從潛行以偷襲、伏擊或邪惡攻擊起手；戰鬥外建議潛行；從兩個連擊點起使用切割，單人受傷時使用養精蓄銳與腎擊，四個連擊點時使用剔骨（目標即將死亡時為兩個），邪惡攻擊。提醒：學會後的毒藥、腳踢、單人時使用閃避。"
L["rm.retail.rogue.assassination.Name"] = "暴雪戰鬥助手"
L["rm.retail.rogue.assassination.Description"] = "推薦至暗之夜的刺殺專精使用。在戰鬥中，遊戲現在會對插件隱藏你的流血效果、增益效果、能量、冷卻時間與生命力，因此它會顯示暴雪自己的戰鬥助手建議（一鍵循環，它會處理潛行起手、絞喉、割裂、毒化、死亡印記與王禍），並在你施法或沒有選取敵人時停止。提醒它未包含的內容：兩波拉怪之間的一種致命毒藥、一種非致命毒藥與潛行、戰鬥中不在潛行狀態時使用消失、對可中斷的施法使用腳踢（只會在遊戲允許讀取該施法的場合亮起）。正式版中生命力是隱藏的，因此赤紅藥瓶由你決定。"
L["rm.retail.rogue.assassination.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.rogue.assassination.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 與 SimulationCraft 的施放順序依計時維持流血效果，而至暗之夜會在戰鬥中隱藏這些資訊；正式版中能量是隱藏的，因此其能量囤積未納入。潛行中先使用絞喉，然後使用伏擊。連擊點數未滿時在絞喉剩餘最後 30% 時刷新絞喉，5 點以上連擊點數時在割裂剩餘最後 30% 時刷新割裂；5 點以上連擊點數時使用憐憫之擊或毒化；不足 5 點時：三個以上敵人使用赤紅風暴，近處有兩個以上敵人時使用飛舞刀刃，伏擊，截肢。提醒：兩種流血效果都生效時使用死亡印記、同時使用王禍、死亡印記就緒時使用消失、對帶有亡靈哨兵印記的目標使用毒襲、戰鬥中只要就緒就使用菊花茶，以及共用的毒藥、潛行與腳踢提醒。"
L["rm.retail.rogue.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.rogue.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是盜賊的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個盜賊內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.retail.rogue.outlaw.Name"] = "暴雪戰鬥助手"
L["rm.retail.rogue.outlaw.Description"] = "推薦至暗之夜的暴徒專精使用。顯示暴雪的戰鬥助手建議（它會處理潛行起手、命運之骰、劍刃亂舞、能量刺激、正中眉心與終結技），並在你施法或沒有選取敵人時停止。提醒它未包含的內容：兩波拉怪之間的毒藥與潛行、戰鬥中不在潛行狀態時使用消失、腳踢。正式版中生命力是隱藏的，因此赤紅藥瓶由你決定。骰個不停由你自行處理：遊戲會隱藏你擁有幾個命運之骰增益效果。"
L["rm.retail.rogue.outlaw.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.rogue.outlaw.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins、SimulationCraft 與 Wowhead 的施放順序需要讀取命運之骰增益效果、大好機會層數與能量，而至暗之夜會在戰鬥中隱藏它們。潛行中使用伏擊。連擊點數距離滿值只差一點或已滿時：正中眉心，狂舞殘殺，憐憫之擊，抹殺。否則無畏觸發時使用伏擊，大好機會達到六層時使用手槍射擊（連擊點數偏低時三層即可），伏擊，邪惡攻擊。提醒：沒有骰子增益時使用命運之骰、連擊點數不超過兩點時使用能量刺激、兩個以上敵人時維持劍刃亂舞、劍刃猛攻、能量刺激、正中眉心與劍刃猛攻都在冷卻時使用備戰。骰個不停需要手動使用。"
L["rm.retail.rogue.subtlety.Name"] = "暴雪戰鬥助手"
L["rm.retail.rogue.subtlety.Description"] = "推薦至暗之夜的敏銳專精使用。顯示暴雪的戰鬥助手建議（它會處理潛行起手、暗影之刃、破喉之咬、暗影之舞、幻影秘技與終結技），並在你施法或沒有選取敵人時停止。提醒它未包含的內容：兩波拉怪之間的毒藥與潛行、對可中斷的施法使用腳踢。正式版中生命力是隱藏的，因此赤紅藥瓶由你決定。"
L["rm.retail.rogue.subtlety.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.rogue.subtlety.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 與 SimulationCraft 的施放順序會為幻影秘技保留暗影之舞，並需要讀取暗影之舞、深沉暗夜與能量，而至暗之夜會在戰鬥中隱藏它們。拉怪前處於潛行狀態：暗影打擊。連擊點數距離滿值只差一點或已滿時：有深沉暗夜時使用剔骨，暗影之舞期間使用幻影秘技，憐憫之擊，三個以上敵人時使用黑火藥，剔骨。否則使用暗影打擊，兩個以上敵人時使用手裏劍風暴，幽暗刃或背刺。提醒：暗影之舞期間使用破喉之咬、暗影之舞就緒時使用暗影之刃、幻影秘技就緒或暗影之刃生效時，在連擊點數不超過兩點（或達到六點以上）時使用暗影之舞、不在潛行狀態且連擊點數不超過兩點時使用消失。"
L["rm.sod.rogue.dps.Name"] = "近戰 DPS（探索賽季）"
L["rm.sod.rogue.dps.Description"] = "探索賽季，1–60 級，符文會在你紋刻後納入使用；綜合 模擬器 第 6 階段、Icy Veins 與 Zockify 第 8 階段。潛行時：暗影打擊，隊伍中絞喉，持有匕首時以伏擊作為背刺配置，單人時偷襲。三個以上敵人與你交戰時：先使用短槍、赤紅風暴、飛舞刀刃。接著割喉觸發時使用伏擊（持有匕首時），維持三層刀劍斬擊，四層毒藥時使用塗毒小刀，從兩個連擊點起使用切割（四點起續上，除非已紋刻直取要害），沒有人使用破甲攻擊或維持皮脂腺毒時負責破甲，已紋刻大屠殺時使用流血效果（赤紅風暴，否則割裂；有刀劍斬擊時不使用），五個連擊點時使用毒化（紋刻前用剔骨），以及依手部符文決定的累積連擊點技能：截肢、刀劍斬擊、背刺（持有匕首時），否則邪惡攻擊。提醒：每把武器上的臨時附魔、腳踢、菊花茶、劍刃亂舞、能量刺激、冷血與閃避，以及已紋刻敏銳大師時用來續上它的消失與伺機待發。"
L["rm.sod.rogue.dps.icyveins.Name"] = "近戰 DPS，為大屠殺維持割裂（探索賽季，Icy Veins）"
L["rm.sod.rogue.dps.icyveins.Description"] = "Icy Veins 的探索賽季順序，作為推薦的探索賽季近戰傷害輸出內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。每個終結技都在五個連擊點時使用，首先在缺少或即將結束時使用切割，然後在已紋刻大屠殺時維持割裂，然後是毒化；塗毒小刀只在五層毒藥時使用；三個敵人時使用短槍或飛舞刀刃。潛行起手、累積連擊點技能與提醒都與推薦的探索賽季內建循環相同；維持皮脂腺毒由你自行處理。"
L["rm.sod.rogue.dps.zockify.Name"] = "近戰 DPS，精簡毒化（探索賽季，Zockify）"
L["rm.sod.rogue.dps.zockify.Description"] = "Zockify 的精簡探索賽季清單，作為推薦的探索賽季近戰傷害輸出內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。不使用流血效果，也不使用破甲。四層毒藥時使用塗毒小刀，缺少時使用切割（兩個連擊點起，有刀劍斬擊時四點起），五個連擊點時使用毒化，然後是手部符文的累積連擊點技能。消失與冷血的爆發由你自行處理。"
L["rm.sod.rogue.tank.Name"] = "坦克（探索賽季）"
L["rm.sod.rogue.tank.Description"] = "探索賽季的坦克，已紋刻不過是點皮肉傷時選用；綜合 模擬器 第 6 階段、Icy Veins、Zockify 與 Warcraft Tavern。還擊，左右開弓冷卻結束即使用，從一個連擊點起使用劍刃之舞（三點起續上），從三點起使用切割（四點起續上），三個以上敵人時使用飛舞刀刃、赤紅風暴與短槍，劍刃之舞生效時使用短槍，兩個增益效果都生效時在五個連擊點使用剔骨，能量低時使用塗毒小刀，然後是刀劍斬擊、截肢或邪惡攻擊。提醒：隊伍中你的目標攻擊其他人時使用戲弄、腳踢、生命力低於一半時使用閃避、劍刃亂舞、能量刺激、菊花茶與武器毒藥（只有持有副手武器時才使用副手毒藥）。暗影閃現與維持皮脂腺毒由你自行處理。"
L["rm.tbc.rogue.dps.simulator.Name"] = "近戰 DPS（模擬器）"
L["rm.tbc.rogue.dps.simulator.Description"] = "1–70 級，所有專精。潛行時：預謀，接著單人時偷襲、隊伍中絞喉，否則伏擊（主手持匕首時）。戰鬥中：還擊，兩個連擊點起使用切割（在最後兩秒內續上），對即將死亡的目標使用剔骨，五個連擊點時若割裂能持續夠久則使用割裂（劍刃亂舞順劈期間除外），否則使用剔骨。目標沒有攻擊你時以截肢或背刺（匕首）累積連擊點，否則以出血或邪惡攻擊。會提醒你缺少的毒藥、腳踢、劍刃亂舞與能量刺激、冷血以及閃避。破甲、腎擊、佯攻、消失與站位由你自行處理。"
L["rm.tbc.rogue.dps.wowhead.Name"] = "近戰 DPS（Wowhead）"
L["rm.tbc.rogue.dps.wowhead.Description"] = "1–70 級，所有專精，遵循 Wowhead。潛行起手、累積連擊點技能與提醒都與 模擬器 版本相同，但切割從一個連擊點起就使用，每個五連擊點終結技都是剔骨：不使用割裂。破甲、腎擊、佯攻、消失與站位由你自行處理。這是推薦的 模擬器 近戰傷害輸出內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
